%[text] # Exploration
%[text] The `eeg.m` script illustrates problems and solutions. This live script looks more generally at how simulation parameters affect performance.
%[text:tableOfContents]{"heading":"Table of Contents"}
%[text] 
%%
%[text] %[text:anchor:H_D32E8D0B] ## Setup Simulation
%[text] First define the stimulation and recording parameters.
run('../startup.m'); % Make sure all toolboxes are on the path

defaults.reproducible              = true;    % Fix the random number generator to get reproducible results
%[text] Equipment:
defaults.stimulatorSamplingRate    = 1e3;     % 1 kHz
defaults.recordingSamplingRate     = 5e3;     % 5kHz
defaults.currentResolution         = 1e-6;    % 1 muA
defaults.highPass                  = 0.01;    % Analog filter of the recording amplifier
defaults.lowPass                   = 100; 
%[text] Experiment:
defaults.duration                  = 2*60;   % 2 min of data
defaults.tacsFrequency             = 10;
defaults.tacsAmplitude             = 0;
defaults.tdcsMean                  = 0;
%[text] Signals. Setting everything except the background to 0.
defaults.additive                  = 100e-6;   % Background Noise stdev
defaults.lfpAmplitude              = 100e-6;
defaults.lfpFrequency              = 8;
defaults.lfpPeakWidth              = 1;
defaults.multiplicative            = 0;
defaults.zAmplitude                = 0;

%[text] And setup the base parameters for artifiact removal
ar = [];
ar.recordingSamplingRate = defaults.recordingSamplingRate; % Match to the recording
ar.segmentDuration       = 3;
ar.segmentDuration       = 30/defaults.tacsFrequency;      % 30 cycles per segment
ar = namedargs2cell(ar); % For easy reuse below.

%[text] Setup the parameters for three artifact removal algorithms to explore.

fastr = [];
fastr.name = "FASTR";
fastr.options.slack = 5e-3;
fastr.options.nrSegsPerWindow = 10;
fastr.options.pcaNr = 2;
fastr.options.pcaVarExplained = Inf;
fastr.options.pcaNrSegsPerWindow = Inf;
fastr.options.referenceSegment = 1;

fbar= [];
fbar.name = "FBAR";
fbar.options.frequencyLimits = [-1 1];

rbar = [];
rbar.name = "RBAR";
rbar.options = [];
%%
%[text] ## Signal frequency dependence
%[text] The analysis in eeg.m focuses only on a single intrinsic oscillation, here I do repeat this for a range of frequencies to show that the relative performance of the methods is approximately the same no matter what the neural signal is. 
A                  = artSim(defaults); % Start fresh

methods = {fastr,fbar,rbar};
signalFreqs = 2.^(0:5);  % Test these frequencies
nrFreqs = numel(signalFreqs);
nrMethods = numel(methods);
forbiddenBand = nan(nrFreqs,nrMethods);
forbidden = nan(nrFreqs,nrMethods);
mre = nan(nrFreqs,nrMethods);
for m=1:nrMethods
    for  f = 1:nrFreqs
        A.lfpFrequency = signalFreqs(f);
        A.sim;
        [arResults] = artifactRemoval(A.vContaminated,methods{m},ar{:},vRecordTcs = A.vRecordTcs);     
        results = analyzeEEG(A,arResults.signal,freqRes=frequencyResolution,axs=[]);
        forbiddenBand(f,m) = results.forbiddenBand;
        forbidden(f,m) = results.forbidden;
        mre(f,m) = results.meanPctError;
    end
end
clf;
subplot(1,2,1)
plot(signalFreqs,forbidden)
xlabel 'Signal Frequency (Hz)'
ylabel 'Forbidden (Hz)'

subplot(1,2,2)
plot(signalFreqs,forbiddenBand)
xlabel 'Signal Frequency (Hz)'
ylabel 'Forbidden Band (Hz)'
legend(cellfun(@(x) x.name,methods));
mean(forbidden)
std(forbidden)
mean(mre)
%[text] The figure shows that FASTR  performs poorly across all signal frequencies while FBAR and RBAR create relatively small forbidden bands, as long as the signal frequency (i.e. the neural oscillation) is distinct from the tACS frequency.
%%
%[text] ## Segment length dependence
%[text] Longer segments generally result in better artifact estimation (as long as the artifact is not substantially the same as the neural signal) and therefore better artifact removal. 
%[text] Note, however, that this comes at a cost of a reduced ability to follow changes in the artifacts over time (i.e. dealing with non-stationary artifacts). The artifacts in these simulations are approximately stationary and therefore ignore this tradeoff. 
A = artSim(defaults);
A.duration         = 600;
A.lfpFrequency     = 23;
A.lfpAmplitude     = 100e-6;    % Oscillation peak amplitude
A.lfpPeakWidth     = 5;        % Oscillation bandwidth.
A.additive         = 100e-6;   % Background
A.zAmplitude       = 0.05;     % 5% heartbeat artifact
A.zFun             = @zHeartbeat;
A.reproducible     = false;    % Random draws each sim
tacsFrequency      = 10;
segmentDuration     =   [1 5 10 20 40];
nrBootstrap         =10;  % Takes a while to run...

nrSegmentDurations = numel(segmentDuration);
stims = ["AC" "DC"];
nrStims = numel(stims);
forbidden = nan(nrSegmentDurations,nrMethods,nrStims,nrBootstrap);
mre = nan(nrSegmentDurations,nrMethods,nrStims,nrBootstrap);

for bs = 1:nrBootstrap
    for stim = 1:nrStims
        if stims(stim)=="AC"
            A.tacsAmplitude  = 1e-3;
            A.tacsFrequency  =tacsFrequency;
            A.tdcsMean  = 0;
        elseif stims(stim)== "DC"
            A.tacsAmplitude  = 0;
            A.tacsFrequency  =0;
            A.tdcsMean  = 1e-3;
        end
        A.sim;
        for m=1:nrMethods
            for  s = 1:nrSegmentDurations
                if stims(stim)=="AC"                    
                    thisTacsFrequency = tacsFrequency;
                elseif stims(stim) =="DC"                    
                    thisTacsFrequency = 0;
                end

                  [arResults] = artifactRemoval(A.vContaminated,methods{m},ar{:}, ...
                                                                segmentDuration = segmentDuration(s), ...
                                                                tacsFrequency = thisTacsFrequency,...
                                                                vRecordTcs = A.vRecordTcs);     
                results = analyzeEEG(A,arResults.signal,freqRes=frequencyResolution,axs=[]);
                forbidden(s,m,stim,bs) = results.forbiddenBand;
                mre(s,m,stim,bs) = results.meanPctError;
            end
        end
    end
end
%%

mForbidden = mean(forbidden,4);
mMre  = mean(mre,4);
sdForbidden = std(forbidden,0,4);
sdMre = std(mre,0,4);

[f,axs] = fig('Name','SegmentDuration','paperCols',1,'height',5,'nrRows',1,'nrCols',1); %[output:2f359f33]
tiledlayout('flow') %[output:2f359f33]
for m=1:nrMethods %[output:group:387fbc9d]
    nexttile %[output:2f359f33]
    yyaxis left
    ploterr(segmentDuration',squeeze(mForbidden(:,m,:)),squeeze(sdForbidden(:,m,:)));
    xlabel 'Segment (s)'
    ylabel 'Forbidden (Hz)'
    yyaxis right
    ploterr(segmentDuration',squeeze(mMre(:,m,:)),squeeze(sdMre(:,m,:)))
    ylabel 'mre (%)'
    title (methods(m))    
end %[output:group:387fbc9d]



%[text] The figure confirms that the mre decrease rapidly with increasing segment duration in RBAR  and FBAR. 
%[text] FASTR has some oddities with longer segment durations, but that is probably due to the way the averaging is done across segments. 
